package com.evt2.board.link

import org.junit.Assert.assertArrayEquals
import org.junit.Assert.assertEquals
import org.junit.Test

/**
 * Cross-checks this Kotlin port against real output from tools/evt2_cli.py's
 * build_frame() -- the SAME framing function already validated byte-for-byte
 * against real EVT2 hardware throughout Phase 1/2 testing (hundreds of
 * HELLO/DATA_CHUNK/etc exchanges over the real USB link). Vectors below were
 * generated by running (from EVT2/tools/):
 *
 *   python -c "
 *   from evt2_cli import build_frame
 *   print(build_frame(0x01, 0, 0, bytes([1])).hex())
 *   print(build_frame(0x04, 42, 7, bytes([0x7E,0x7D,0x01,0x02,0xFF])).hex())
 *   print(build_frame(0x06, 1000, 123456, b'').hex())
 *   "
 *
 * NOTE: these vectors use VER=1 (Protocol.PROTOCOL_VERSION), NOT the
 * usb_encrypt_host reference's VER=2 -- ported from that project's own
 * ProtocolTest.kt structure, but every hex string here is freshly generated
 * against EVT2's actual command_protocol.c framing, not copied.
 */
class ProtocolTest {

    private fun hexToBytes(hex: String): ByteArray =
        ByteArray(hex.length / 2) { ((Character.digit(hex[it * 2], 16) shl 4) + Character.digit(hex[it * 2 + 1], 16)).toByte() }

    private fun bytesToHex(bytes: ByteArray): String = bytes.joinToString("") { "%02x".format(it) }

    @Test
    fun `encodePacket matches evt2_cli py build_frame for HELLO`() {
        val expected = "7e0101000000000000010001b35f0e337e"
        val actual = encodePacket(PacketType.HELLO.value, 0, 0, byteArrayOf(1))
        assertEquals(expected, bytesToHex(actual))
    }

    @Test
    fun `encodePacket matches evt2_cli py build_frame for DATA_CHUNK with escaped bytes`() {
        val expected = "7e01042a000700000005007d5e7d5d0102ff3481e7447e"
        val actual = encodePacket(
            PacketType.DATA_CHUNK.value, 42, 7,
            byteArrayOf(0x7E.toByte(), 0x7D.toByte(), 0x01, 0x02, 0xFF.toByte()),
        )
        assertEquals(expected, bytesToHex(actual))
    }

    @Test
    fun `encodePacket matches evt2_cli py build_frame for ACK with empty payload`() {
        val expected = "7e0106e80340e2010000003da77ffb7e"
        val actual = encodePacket(PacketType.ACK.value, 1000, 123456, ByteArray(0))
        assertEquals(expected, bytesToHex(actual))
    }

    @Test
    fun `FrameDecoder round-trips a frame containing escaped FLAG and ESC bytes`() {
        val originalPayload = byteArrayOf(0x7E.toByte(), 0x7D.toByte(), 0x01, 0x02, 0xFF.toByte())
        val frame = hexToBytes("7e01042a000700000005007d5e7d5d0102ff3481e7447e")

        val decoder = FrameDecoder()
        val packets = decoder.feed(frame)

        assertEquals(1, packets.size)
        val pkt = packets[0]
        assertEquals(PacketType.DATA_CHUNK.value, pkt.type)
        assertEquals(42, pkt.sessionId)
        assertEquals(7L, pkt.seq)
        assertArrayEquals(originalPayload, pkt.payload)
    }

    @Test
    fun `FrameDecoder resyncs after a corrupted frame`() {
        val goodFrame = encodePacket(PacketType.PING.value, 1, 1, ByteArray(0))
        val corrupted = goodFrame.copyOf().also { it[3] = (it[3].toInt() xor 0xFF).toByte() } // flip a header byte -> CRC mismatch

        val decoder = FrameDecoder()
        val fromCorrupted = decoder.feed(corrupted)
        val fromGood = decoder.feed(goodFrame)

        assertEquals(0, fromCorrupted.size)
        assertEquals(1, fromGood.size)
        assertEquals(PacketType.PING.value, fromGood[0].type)
    }

    @Test
    fun `encodePacket rejects payload larger than MAX_PAYLOAD`() {
        val oversized = ByteArray(Protocol.MAX_PAYLOAD + 1)
        try {
            encodePacket(PacketType.DATA_CHUNK.value, 0, 0, oversized)
            throw AssertionError("expected ProtocolException")
        } catch (_: ProtocolException) {
            // expected
        }
    }

    @Test
    fun `FrameDecoder round-trips a DECRYPT_CHUNK and DECRYPTED_CHUNK pair -- EVT2 extension, no reference equivalent`() {
        val nonce = ByteArray(12) { it.toByte() }
        val tag = ByteArray(16) { (it + 100).toByte() }
        val ciphertext = byteArrayOf(0x11, 0x22, 0x33)
        val requestFrame = encodePacket(PacketType.DECRYPT_CHUNK.value, 5, 9, nonce + tag + ciphertext)

        val decoder = FrameDecoder()
        val packets = decoder.feed(requestFrame)
        assertEquals(1, packets.size)
        assertEquals(PacketType.DECRYPT_CHUNK.value, packets[0].type)
        assertEquals(9L, packets[0].seq)
        assertArrayEquals(nonce + tag + ciphertext, packets[0].payload)
    }
}
